import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import crypto from 'node:crypto';
import { execFileSync } from 'node:child_process';

const work = process.argv[2];
if (!work || !fs.existsSync(work)) throw new Error('Payments total/reader patch: reconstructed work directory is required');

const archive = Buffer.from("[... ELLIPSIZATION ...]", 'base64');
const expectedArchiveHash = '6afa32d5bb21285e628e85d0baa85f1e3e8e5e22b9ea4fbc072e7df40a95b3f7';
const actualArchiveHash = crypto.createHash('sha256').update(archive).digest('hex');
if (actualArchiveHash !== expectedArchiveHash) throw new Error('Payments total/reader archive hash mismatch: ' + actualArchiveHash);

const archivePath = path.join(os.tmpdir(), 'transsalomao-payments-total-reader-' + process.pid + '.tar.xz');
fs.writeFileSync(archivePath, archive);
try {
  execFileSync('xz', ['-t', archivePath], { stdio: 'inherit' });
  execFileSync('tar', ['-xJf', archivePath, '-C', work], { stdio: 'inherit' });
} finally {
  fs.rmSync(archivePath, { force: true });
}

const checks = {
  'src/routes/dono/pagamentos.tsx': '25458222e2941ff294a5e7f351874535e609ddeab09359b988bae15d4b2e090a',
  'src/components/financial-document-reader.tsx': 'd4cca2ffe1566ebeda0d451be6deb7a301926493884e56b6d0671c1dd0e4c66e',
  'src/routes/api/ler-comprovante-financeiro.ts': 'd5a42d31311e4b7c19f46e16c6a25ba532e8d56c53069e66c88f7943551c0874',
};
for (const [rel, expected] of Object.entries(checks)) {
  const file = path.join(work, rel);
  if (!fs.existsSync(file)) throw new Error('Payments total/reader patch missing file: ' + rel);
  const actual = crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
  if (actual !== expected) throw new Error('Payments total/reader file mismatch: ' + rel + ' => ' + actual);
}

console.log('[payments-total-reader] total period + payment PDF/photo reader applied');
